    function setFHEConfig(FHEConfig memory fheConfig) internal {
        FHEConfig storage $ = getFHEConfig();
        $.ACLAddress = fheConfig.ACLAddress;
        $.FHEExecutorAddress = fheConfig.FHEExecutorAddress;
    }

